-- 1217: туры «Местечка Камчатка» (mestechkokam.ru) на карточку 1216 (#2349).
--
-- Основание — то же, что у 1216: владелец 12.10 предложил оператору подключить
-- туры в публичный MCP («мне нужно только ваше ДА, и мои ИИ сами всё сделают,
-- вам останется проверить»), оператор ответил «ДА». Источник — витрина
-- оператора, снятая 12.10.2026 из песочницы: 20 карточек экскурсий с ценами,
-- составом и списком «что взять», страницы-списки категорий (там длительность
-- в часах и размер вертолётной группы) и каталог.
--
-- В базу идут 18 туров. Два с сайта НЕ переносятся, потому что цены у них на
-- сайте нет: рыбалка на базе «Утёс» («рассчитывается индивидуально») и хели-ски
-- (группа 6–12, февраль–май, без суммы). Колонка base_price NOT NULL, а число
-- за оператора — выдумка (§4.0). Заготовка /api/admin/import-mestechko ставила
-- им 80 000 и 250 000 — удалена этим же PR.
--
-- ── Цены: что сходится, что нет ───────────────────────────────────────────
-- Цена берётся с карточки тура («Стоимость экскурсии») и сверена со
-- страницей-списком категории и каталогом. У 15 туров все три места сходятся —
-- они опубликованы (is_published = TRUE). У трёх сайт противоречит сам себе,
-- и они заведены ЧЕРНОВИКАМИ (is_published = FALSE) — публикует оператор из
-- кабинета, когда назовёт цену:
--   • «Долина гейзеров и вулкан Толбачик» — карточка 170 000, список и каталог
--     180 000;
--   • «Бухта Русская» — карточка и список 20 000, второй блок и каталог 16 000;
--   • «Остров Старичков» — карточка и список 12 000, второй блок и каталог 9 000.
-- В черновик записана цена карточки, в price_note названа вторая цифра.
-- Отдельный блок-анонс на странице «Вопрос-ответ» несёт третий набор цен
-- (Курильское 70 000, Долина гейзеров 70 000 и туры «из Мильково», которых на
-- сайте нет) — это не карточки туров, в расчёт не берётся, но оператору
-- названо в #2349.
--
-- ── Что ещё с сайта ───────────────────────────────────────────────────────
--   • длительность — из списков категорий («8–10 часов» → 9), многодневный
--     Толбачик — «4 дня»; у вертолётных, где список говорит «1 день», —
--     сумма отрезков программы на карточке;
--   • состав («Что входит в стоимость») и «Что взять с собой» — дословно;
--   • программа — только у вертолётных туров, где на сайте она разбита по
--     шагам; у джип-туров описание повествовательное, программу из него не
--     сочиняем;
--   • размер вертолётной группы — из списка категории (18–22 / 18–20);
--     у джип-, морских и снегоходных туров вместимость на сайте не названа —
--     технический потолок 15, как у «Края Вулканов» (вопрос оператору);
--   • подвоз: джип и снегоход — «выезд из гостиницы» / «трансферы из/в
--     гостиницу» → hotel_pickup; вертолёт — вылет из аэропорта Елизово в
--     10:00, сбор за 2–2,5 часа → meeting_point; морские — «выход из порта»
--     без адреса → NULL («не записано»), готовность к чужим витринам у них
--     не наступит, пока оператор не назовёт место;
--   • скидка детям до 10 лет 10% на джип-туры и условия оплаты (по договору
--     на счёт юрлица, невозвратная часть предоплаты, полная сумма за 30–45
--     дней) — в price_note, это слова сайта;
--   • координаты — главное место тура из базы Ведара (places через MCP
--     get_place_info 12.10); у озера Толмачёва координата в базе не
--     подтверждена — NULL, а не догадка.
--
-- ── Что НЕ переносится, и почему ──────────────────────────────────────────
--   • даты и сезон: сайт называет месяцы в тексте («июнь — октябрь»,
--     «круглогодично»), они оставлены в описании; окно сезона — решение
--     владельца, как у «Края Вулканов» (1183), здесь не ставится;
--   • условия отмены: на сайте их нет (есть только невозвратная предоплата);
--     поле пусто, пока оператор не назовёт своё;
--   • «не входит»: сайт этого не перечисляет у экскурсий;
--   • сложность — наша оценка по тексту сайта (пешая часть, восхождение);
--     оператор поправит в кабинете.
--
-- ── Фото ──────────────────────────────────────────────────────────────────
-- По 5 первых снимков галереи с каждой карточки (у Толмачёва на сайте 2, у
-- вертолёта к Толбачику 4, у снегоходов 2 и 3). Скачаны 12.10 из песочницы,
-- сжаты sharp до 1600px/q80 в public/images/mestechko/, варианты 320/640/1280
-- webp — npm run images. Права на снимки — у оператора; размещение — по его
-- «ДА» на предложение владельца, где туры и фото уходят на витрину. Hero —
-- первый снимок. Пишутся только туда, где фото ещё нет.
--
-- Цена: price_unit = 'per_person' явно (дефолт колонки — per_tour).
-- Идемпотентна: вставка только при наличии партнёра и отсутствии slug;
-- id сравниваются текстом.

INSERT INTO operator_tours (
  operator_id, title, slug, short_description, description,
  location_type, activity_type, location_name, latitude, longitude,
  base_price, currency, price_unit, min_participants, max_participants,
  duration_hours, duration_type, multi_day_count,
  weather_dependent, difficulty, is_active, is_published,
  program, included, what_to_bring, safety_notes,
  pickup_type, pickup_details, meeting_point,
  photos, tour_image,
  price_note, source_url,
  created_at, updated_at
)
SELECT
  p.id, v.title, v.slug, v.short_d, v.descr,
  v.loc_type, v.act_type, v.loc_name, v.lat, v.lng,
  v.price, 'RUB', 'per_person', 1, v.max_p,
  v.dur_h, v.dur_type, v.days,
  v.weather, v.diff, TRUE, v.published,
  v.program, v.included, v.bring, v.safety,
  v.pickup_type, v.pickup, v.pickup,
  v.photos, v.photos[1],
  v.price_note, v.source_url,
  NOW(), NOW()
FROM partners p
CROSS JOIN (VALUES
