       program, included, bring, safety, pickup_type, pickup, photos,
       price_note, source_url)
WHERE p.slug = 'mestechko'
  AND NOT EXISTS (
    SELECT 1 FROM operator_tours t
     WHERE t.operator_id::text = p.id::text AND t.slug = v.slug
  );

DO $$
DECLARE n INT;
BEGIN
  SELECT COUNT(*) INTO n FROM operator_tours t
   JOIN partners p ON p.id::text = t.operator_id::text
  WHERE p.slug = 'mestechko' AND t.deleted_at IS NULL;
  IF n <> 18 THEN
    RAISE WARNING '1217: у карточки mestechko % туров, ожидалось 18', n;
  END IF;
END $$;
